"""Generated headline table for the final job (numbers only from runs/final01/<panel>/summary.json + audit.json).
Usage: make_final_table.py [runs/final01] -> FINAL-TABLE.md + final_table.json in that run dir."""
import hashlib, json, sys
from pathlib import Path

run = Path(sys.argv[1] if len(sys.argv) > 1 else Path(__file__).resolve().parent / 'runs' / 'final01').resolve()
PANELS = [('final01', 'A: pre-registered selection'), ('final01b', 'B: addendum 1+2 selection (validation)'), ('final256', 'A frozen at 256^3 (addendum 3)')]
BAR = 0.01
out, lines = [], []
for panel, label in PANELS:
    d = run / panel
    if not (d / 'summary.json').exists(): continue
    raw = (d / 'summary.json').read_bytes(); s = json.loads(raw); audit = json.loads((d / 'audit.json').read_text())
    res = json.loads((run / 'pull' / 'out' / panel / 'results.json').read_text()); model = res['config']['model']
    R = int(model['bank'].split('_R')[1].split('/')[0]); K = int(model['head'].split('_K')[1].split('.')[0])
    for m in s['meshes']:
        rows = {r['method']: r for r in m['rows']}; named = next(r for r in m['rows'] if r['method'].endswith('_NAMED'))
        for r in m['rows']:
            if not r['method'].startswith('nmrom'): continue
            q = int(r['method'].split('_q')[1].split('_')[0]); f = r.get('fastest_fom_error_le_rom_all_times')
            fe = rows[f['method']]['error_all_times_worst'] if f else None
            out.append(dict(panel=panel, label=label, cohort=m['cohort'], mesh=m['intervals'], R=R, K=K, q=q, method=r['method'],
                            err_all=r['error_all_times_worst'], err_evolved=r['error_evolved_worst'], rom_ms=r['device_ms_median'],
                            cases=r['cases'], timed_cases=r['timed_cases'], failures=r['failures'], named_ms=named['device_ms_median'],
                            named_err=named['error_all_times_worst'], speedup_named=r['speedup_vs_named_fom'],
                            fom=f and f['method'], fom_ms=f and f['device_ms'], fom_err=fe, speedup_fom_rule=f and f['speedup'],
                            accuracy_bar=r['error_all_times_worst'] <= BAR, audit_passed=audit['passed'],
                            summary_sha256=hashlib.sha256(raw).hexdigest(), gpu=s['metadata']['gpu'], job=s['metadata']['job_id']))
(run / 'final_table.json').write_text(json.dumps(out, indent=1) + '\n')
lines.append(f'# {run.name} — generated headline table\n')
lines.append('Generated by `make_final_table.py` from `runs/final01/<panel>/summary.json`; no number typed by hand. Errors: worst over cases of the maximum over ALL output times (t=0 included) of same-grid relative L2 error; "evolved" excludes t=0. Times: GPU-query median over 5 repetitions × all cases, one H200 allocation. FOM rule: fastest tested CN-CG setting with all-times error ≤ the row\'s.\n')
lines.append('| panel | cohort | mesh | R | K | q | method | err all-times % | err evolved % | NM-ROM ms | FOM setting (rule) | FOM ms | FOM err % | speedup (rule) | named ms | speedup vs named | failed solves | ≤1 % |')
lines.append('|---|---|---:|---:|---:|---:|---|---:|---:|---:|---|---:|---:|---:|---:|---:|---:|---|')
for e in out:
    lines.append(f"| {e['panel']} | {e['cohort']} | {e['mesh']}^3 | {e['R']} | {e['K']} | {e['q']} | {e['method'].replace('nmrom_', '')} | {100*e['err_all']:.4f} | {100*e['err_evolved']:.4f} | "
                 f"{e['rom_ms']:.2f} | {e['fom'] or '-'} | {e['fom_ms'] if e['fom_ms'] is None else round(e['fom_ms'], 2)} | "
                 f"{'-' if e['fom_err'] is None else f'{100*e['fom_err']:.4f}'} | {'-' if e['speedup_fom_rule'] is None else f'{e['speedup_fom_rule']:.2f}'} | "
                 f"{e['named_ms']:.2f} | {e['speedup_named']:.2f} | {e['failures']} | {'PASS' if e['accuracy_bar'] else 'miss'} |")
lines.append('\n## Glossary\n- **panel A**: arms chosen by the rule pre-registered in DESIGN.md (R320/K32; zero-failure rule admitted no q, fallback = lowest validation error, q=288). **panel B**: arms chosen mechanically on validation after addenda 1–2 (R256/K16, q=160; LM tolerance 1e-4, Cholesky, 1 start; direct arm with moments initial fit).\n- **R**: bank size (learned coordinate functions). **K**: nonlinear head latent size. **q**: number of linear correction directions (q=0 fast setting).\n- **cn**: reduced Crank–Nicolson weak steps (dt 0.025, 20 solves); **direct**: each output fitted to exactly propagated sine moments (linear autonomous PDE only; labelled).\n- **sealed_921099_never_opened**: 64 draws never evaluated before this job. **paper_benchmark_920399_repeated**: the paper\'s Heat 3D cohort (evaluated before; comparability only).\n- **FOM setting (rule)**: fastest tested Crank–Nicolson CG (dt, rtol) whose all-times error ≤ the row\'s NM-ROM error, same allocation. **named**: CN-CG dt 0.025, rtol 1e-6.\n- **failed solves**: non-stationary Levenberg–Marquardt exits (ROM) over all cases and steps.\n')
(run / 'FINAL-TABLE.md').write_text('\n'.join(lines) + '\n'); print('\n'.join(lines[:60]))
